UPDATE lessons SET title='Year 3, Week 26, Lesson 3: Imperative verbs', data=json_patch(data,'{"child_mission":"Imperative verbs give commands or instructions and usually appear at the start of procedure steps.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same strategy to an unfamiliar topic or audience, then compare the effect of two different choices.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nRewrite as imperatives: \"The water needs to be poured\" and \"You can mix the flour.\"\n\nFEEDBACK\nPour the water. Mix the flour.\n\nCHECK\nQuestions are not imperative steps.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nCreate a bank of 15 imperative verbs for cooking, craft and sport. Rewrite five weak steps as strong imperatives and say how the tone becomes clearer.\n\nWrite a short reflection describing one specific revision you made and why.","interactive_activities":null,"learning_area":"English","learning_intention":"Imperative verbs give commands or instructions and usually appear at the start of procedure steps.","lesson_number":3,"lesson_role":"Language and spelling","materials":["Paper or typed answer space","Pencil"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["EN2-VOCAB-01","EN2-SPELL-01"],"parent_notes":"Parent: Marking guidance for the independent task: Create a bank of 15 imperative verbs for cooking, craft and sport. Rewrite five weak steps as strong imperatives and say how the tone becomes clearer. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original demonstration: Stir, Measure, Place and Wait are imperatives. \"You should stir\" is softer ad